        n = len(nums)
        total = 0
        for i in range(n):
            # Check if i - k exists and if nums[i] is strictly greater
            left_ok = True
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    left_ok = False
            # Check if i + k exists and if nums[i] is strictly greater
            right_ok = True
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    right_ok = False
            if left_ok and right_ok:
                total += nums[i]
