class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        if k > n:
            return False

        # We need to find a substring of length k that:
        # 1. Consists of only one distinct character
        # 2. The character immediately before (if exists) is different
        # 3. The character immediately after (if exists) is different

        # We can iterate over all possible starting indices of substrings of length k
        for i in range(0, n - k + 1):
            substring = s[i:i+k]
            # Check if all characters in substring are the same
            if len(set(substring)) == 1:
                char = substring[0]
                # Check character before
                if i > 0:
                    if s[i - 1] == char:
                        continue
                # Check character after
                if i + k < n:
                    if s[i + k] == char:
                        continue
                # If both conditions satisfied, return True
                return True

        return False
