class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            left_exists = i - k >= 0
            right_exists = i + k < n

            # If neither left nor right exists, it's good
            if not left_exists and not right_exists:
                total += nums[i]
            elif left_exists and not right_exists:
                # Only left exists, must be strictly greater than left
                if nums[i] > nums[i - k]:
                    total += nums[i]
            elif not left_exists and right_exists:
                # Only right exists, must be strictly greater than right
                if nums[i] > nums[i + k]:
                    total += nums[i]
            else:
                # Both exist, must be strictly greater than both
                if nums[i] > nums[i - k] and nums[i] > nums[i + k]:
                    total += nums[i]
        return total
