class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Convert each property list to a set for efficient intersection
        sets = [set(p) for p in properties]

        # Build the graph using adjacency list
        # We'll use Union-Find (Disjoint Set Union) to count connected components
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # path compression
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            # union by rank
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # For each pair (i, j) with i < j, check if intersect >= k
        for i in range(n):
            for j in range(i + 1, n):
                # Compute the size of intersection
                inter_size = len(sets[i] & sets[j])
                if inter_size >= k:
                    union(i, j)

        # Count the number of connected components
        # Each node that is its own parent (root) represents a component
        components = set()
        for i in range(n):
            components.add(find(i))

        return len(components)
