MOD = int(sys.stdin.readline())

def is_connected(edges, n):
    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
            return True
        return False

    for u, v in edges:
        if not union(u, v):
            return False
    return len(set(find(i) for i in range(1, n + 1))) == 1

def count_even_odd_distances(n, edges):
    graph = [[] for _ in range(n + 1)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    dist = [-1] * (n + 1)
    def bfs(start):
        queue = [start]
        dist[start] = 0
        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[node] + 1
                    queue.append(neighbor)

    bfs(1)
    even_count = sum(1 for d in dist[1:] if d % 2 == 0)
    odd_count = sum(1 for d in dist[1:] if d % 2 == 1)
    return even_count == odd_count

def solve(n, p):
    results = []
    for m in range(n - 1, n * (n - 1) // 2 - 1, -1):
        if m > n - 1:
            continue
        edges = list(combinations(range(1, n + 1), m))
        count = 0
        for edge_combination in edges:
            if is_connected(edge_combination, n) and count_even_odd_distances(n, edge_combination):
                count += 1
        results.append(count % p)
    return results

