    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        online = [True] * numberOfUsers
        offline_end = [-1] * numberOfUsers
        online_count = numberOfUsers

        # Process offline events first
        for event in events:
            if event[0] == "OFFLINE":
                _, _, uid_str = event
                uid = int(uid_str)
                offline_end[uid] = int(event[1])
                online_count -= 1

        # Process message events
        mentions = [0] * numberOfUsers
        for event in events:
            if event[0] == "MESSAGE":
                _, _, mentions_str = event
                tokens = mentions_str.split()
                for token in tokens:
                    if token == "ALL":
                        for i in range(numberOfUsers):
                            if online[i]:
                                mentions[i] += 1
                    elif token == "HERE":
                        for i in range(numberOfUsers):
                            if online[i]:
                                mentions[i] += 1
                    else:
                        # Handle id<number> tokens
                        for part in token.split():
                            if "<" in part and ">" in part:
                                num_str = part.replace("<", "").replace(">", "")
                                num = int(num_str)
                                if 0 <= num < numberOfUsers:
                                    if online[num]:
                                        mentions[num] += 1

        return mentions
