class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        x, y = 0, 0
        max_dist = 0
        direction_counts = collections.defaultdict(int)

        # Initial counts of directions
        for dir_char in s:
            if dir_char == 'N':
                direction_counts['N'] += 1
            elif dir_char == 'S':
                direction_counts['S'] += 1
            elif dir_char == 'E':
                direction_counts['E'] += 1
            elif dir_char == 'W':
                direction_counts['W'] += 1

        # Calculate initial max distance
        max_dist = max(x, y)

        # Process each move in the string
        for dir_char in s:
            if dir_char == 'N':
                x += 1
            elif dir_char == 'S':
                x -= 1
            elif dir_char == 'E':
                y += 1
            elif dir_char == 'W':
                y -= 1

            # Update max distance
            max_dist = max(max_dist, abs(x) + abs(y))

            # Adjust counts based on the move
            if dir_char == 'N':
                direction_counts['N'] -= 1
            elif dir_char == 'S':
                direction_counts['S'] -= 1
            elif dir_char == 'E':
                direction_counts['E'] -= 1
            elif dir_char == 'W':
                direction_counts['W'] -= 1

        # Apply changes to maximize distance
        # Priority: North (increases x), East (increases y)
        # Calculate how many changes can be made
        changes_north = min(k, direction_counts['N'])
        changes_east = min(k, direction_counts['E'])

        # Apply changes
        x += changes_north
        y += changes_east

        # Update max distance
        max_dist = max(max_dist, abs(x) + abs(y))

        # Apply remaining changes (if any)
        remaining_changes = k - changes_north - changes_east

        # Apply remaining changes: prioritize North (x) then East (y)
        if remaining_changes > 0:
            if x + remaining_changes > 0:
                x += remaining_changes
            elif y + remaining_changes > 0:
                y += remaining_changes

        return max_dist
