def compute_lcs_lengths(S, N):
    # dp[i][j] = length of LCS of S[:i] and j
    dp = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if S[i - 1] == j:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp

def solve(N, M, S):
    dp = compute_lcs_lengths(S, N)

    # Precompute factorials and inverse factorials
    fact = [1] * (M + 1)
    for i in range(1, M + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv_fact = [1] * (M + 1)
    inv_fact[M] = pow(fact[M], MOD - 2, MOD)
    for i in range(M - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    # Precompute binomial coefficients
    binom = [[0] * (M + 1) for _ in range(M + 1)]
    for i in range(M + 1):
        for j in range(M + 1):
            if j > i:
                binom[i][j] = 0
            elif j == 0 or j == i:
                binom[i][j] = 1
            else:
                binom[i][j] = (binom[i - 1][j - 1] + binom[i - 1][j]) % MOD

    # Calculate answers for k=0 to N
    results = []
    for k in range(N + 1):
        if k == 0:
            # All strings with LCS length 0: 26^M
            results.append(fact[M])
        else:
            # Sum of binomial coefficients for LCS length k
            total = 0
            for i in range(k, M + 1):
                total = (total + binom[i][k]) % MOD
            results.append(total)

    return results

