class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        n = len(grid)
        m = len(grid[0])

        # Precompute the maximum sum for each row with at most `l` elements
        max_row_sums = [[0] * (limits[i] + 1) for i in range(n)]

        for i in range(n):
            # Sort row in descending order to get max sum easily
            row = sorted(grid[i], reverse=True)
            for j in range(1, limits[i] + 1):
                max_row_sums[i][j] = max_row_sums[i][j-1] + row[j-1]

        # DP to find max sum with at most `k` elements
        dp = [0] * (k + 1)

        for i in range(n):
            # Traverse backwards to avoid overwriting
            for j in range(k, 0, -1):
                for l in range(1, limits[i] + 1):
                    dp[j] = max(dp[j], dp[j-l] + max_row_sums[i][l])

        return dp[k]
