class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def backtrack(path, used):
            if len(path) == n:
                result.append(path[:])
                return

            if len(used) % 2 == 0:  # Odd position: can place even numbers
                for num in range(1, n + 1):
                    if not used[num - 1]:
                        used[num - 1] = True
                        path.append(num)
                        self.permute(n, k, path, used)
                        path.pop()
                        used[num - 1] = False
            else:  # Even position: can place odd numbers
                for num in range(1, n + 1):
                    if not used[num - 1]:
                        used[num - 1] = True
                        path.append(num)
                        self.permute(n, k, path, used)
                        path.pop()
                        used[num - 1] = False

        result = []
        used = [False] * n
        self.permute(n, k, [], used)

        if len(result) < k:
            return []
        else:
            return sorted(result)[k - 1]
