        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j]:
                    cost[i][j] = cost[i + 1][j - 1]
                else:
                    # Cost to make s[i] and s[j] the same
                    cost[i][j] = float('inf')
                    for c in range(ord('a'), ord('z') + 1):
                        # Cost to change s[i] to c and s[j] to c
                        cost[i][j] = min(
                            cost[i][j],
                            cost[i + 1][j - 1] + min(
                                abs(ord(s[i]) - c) + abs(ord(s[j]) - c),
                                abs(ord(s[i]) - c) + (26 - abs(ord(s[j]) - c)),
                                (26 - abs(ord(s[i]) - c)) + abs(ord(s[j]) - c)
