                else:
                    # If we can make s[i] and s[j] the same
                    if cost[i][j] <= m:
                        dp[i][j][m] = dp[i + 1][j - 1][m - cost[i][j]] + 2
                    else:
                        # Otherwise, take the best by ignoring one end
                        dp[i][j][m] = max(dp[i + 1][j][m], dp[i][j - 1][m])

        # The answer is the best we can get for the whole string with at most k operations
        return dp[0][n - 1][k]
