                indices = index_map[query]
                # Find the minimum distance considering circularity
                min_dist = float('inf')
                for idx in indices:
                    # Distance to the previous index
                    dist1 = (idx - 1 + n) % n
                    # Distance to the next index
                    dist2 = (idx + 1) % n
                    min_dist = min(min_dist, dist1, dist2)
                result.append(min_dist)
            else:
                result.append(-1)

