class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        # Initialize a difference array to apply range updates efficiently
        diff = [0] * (n + 1)

        # Apply each query as a range update
        for l, r, val in queries:
            diff[l] += val
            if r + 1 < n:
                diff[r + 1] -= val

        # Apply the prefix sum to get the final values after all queries
        current = 0
        for i in range(n):
            current += diff[i]
            nums[i] += current

        # Check if all elements are zero
        if all(x == 0 for x in nums):
            return len(queries)
        else:
            return -1
