class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def longest_palindrome(substr: str) -> int:
            n = len(substr)
            if n == 0:
                return 0
            dp = [[False] * n for _ in range(n)]
            max_len = 1
            for i in range(n):
                dp[i][i] = True
            for i in range(n - 1):
                if substr[i] == substr[i + 1]:
                    dp[i][i + 1] = True
                    max_len = 2
            for length in range(3, n + 1):
                for i in range(n - length + 1):
                    j = i + length - 1
                    if dp[i + 1][j - 1] and substr[i] == substr[j]:
                        dp[i][j] = True
                        max_len = max(max_len, length)
            return max_len

        len_s, len_t = len(s), len(t)
        max_palindrome_len = 0

        # Case 1: Take substring from s and empty substring from t
        max_palindrome_len = max(max_palindrome_len, longest_palindrome(s))

        # Case 2: Take empty substring from s and substring from t
        max_palindrome_len = max(max_palindrome_len, longest_palindrome(t))

        # Case 3: Take non-empty substrings from both s and t
        for i in range(len_s):
            for j in range(len_t):
                combined = s[i:] + t[j:]
                max_palindrome_len = max(max_palindrome_len, longest_palindrome(combined))

        return max_palindrome_len
