from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        max_product = -1

        # Iterate over all possible subsequences
        for mask in range(1, 1 << n):
            # Calculate alternating sum and product
            alt_sum = 0
            product = 1
            has_negative = False

            for i in range(n):
                if mask & (1 << i):
                    if i % 2 == 0:
                        alt_sum += nums[i]
                        if nums[i] < 0:
                            has_negative = True
                    else:
                        alt_sum -= nums[i]
                        if nums[i] < 0:
                            has_negative = True
                    product *= nums[i]

            # Check if alternating sum equals k and product is within limit
            if alt_sum == k and product <= limit:
                max_product = max(max_product, product)

        return max_product
