import sys
import math
from collections import defaultdict

def sieve(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(math.sqrt(limit)) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    return [i for i, prime in enumerate(is_prime) if prime]

def is_400_number(n, primes):
    factors = defaultdict(int)
    for p in primes:
        while n % p == 0:
            factors[p] += 1
            n //= p
        if n == 1:
            break
    return len(factors) == 2 and all(k % 2 == 0 for k in factors.values())

def generate_400_numbers(limit):
    primes = sieve(limit)
    numbers = set()
    for p1 in primes:
        power = 1
        while True:
            power *= p1
            if power > limit:
                break
            for p2 in primes:
                if p2 == p1:
                    continue
                power_p2 = 1
                while True:
                    power_p2 *= p2
                    if power_p2 > limit:
                        break
                    candidate = power * power_p2
                    if candidate <= limit:
                        numbers.add(candidate)
                    if power_p2 > limit // p1:
                        break
            if power_p2 > limit // p1:
                break
            power *= p1
    return sorted(numbers)

